async function entrarNaFila(){
  if(!validarEspera()) return;
  ocupado = true;
  atualizarTrava();
  try{
    const r = await api('esperar', {
      telefone: soDigitos($('tel').value),
      nome: $('nome').value.trim()
    });
    naEspera = r.naEspera || null;
    carimbar('NA FILA','fila');
    avisar('Pronto, ' + primeiroNome($('nome').value) + '. ' + (naEspera
      ? 'Você é o ' + naEspera.posicao + 'º da lista de espera.'
      : 'Você entrou na lista de espera.'));
    aplicar(r);
  }catch(err){
    if(err.resposta){
      if(err.resposta.jaConfirmado) jaConfirmado = true;
      if(err.resposta.naEspera) naEspera = err.resposta.naEspera;
    }
    avisar('Não deu para entrar na fila: ' + err.message, 'erro');
    aplicar(err.resposta);                       // se uma vaga abriu no meio do caminho, a página já mostra
  }finally{
    ocupado = false;
    atualizarTrava();
  }
}

